"""A selftest reporter that treats an empty population as a failure."""

def __init__(self, name="", min_n=1, verbose=True):
    self.name = name
    self.min_n = min_n
    self.verbose = verbose
    self.passed = []
    self.failed = []
    self.vacuous = []
    if verbose and name:
        print("selftest %s" % name)

def chk(self, label, condition, n, extra=""):
    """label, condition, and n = the number of cases the condition examined.

    n < min_n  =>  VACUOUS, regardless of `condition`."""
    if n is None:
        raise TypeError(
            "chk() requires a denominator: how many cases did this condition examine? "
            "A check whose author cannot say what it examined examined nothing.")
    n = int(n)
    if n < self.min_n:
        self.vacuous.append((label, n))
        tag = "VACUOUS"
    elif condition:
        self.passed.append((label, n))
        tag = "OK     "
    else:
        self.failed.append((label, n))
        tag = "FAIL   "
    if self.verbose:
        print("  %s %s   [n=%d]%s" % (tag, label, n, ("  " + str(extra)) if extra else ""))
    return tag.strip() == "OK"

def summary(self):
    p, f, v = len(self.passed), len(self.failed), len(self.vacuous)
    tot = p + f + v
    if self.verbose:
        print("  %d/%d passed" % (p, tot), end="")
        if f:
            print(", %d FAILED" % f, end="")
        if v:
            print(", %d VACUOUS (examined nothing: %s)"
                  % (v, ", ".join(l for l, _ in self.vacuous)), end="")
        print()
        if v and not f:
            print("  *** a suite with a vacuous check is NOT a passing suite: the vacuous "
                  "checks are statements about the test, not the world ***")
    return f == 0 and v == 0

# convenience: total cases examined across all checks, for a suite-level denominator
def total_cases(self):
    return sum(n for _, n in self.passed + self.failed + self.vacuous)

